package com.gainser.browser;
import android.annotation.SuppressLint;import android.app.Activity;import android.os.Bundle;import android.webkit.*;
public class MainActivity extends Activity{private WebView webView;@SuppressLint("SetJavaScriptEnabled")@Override protected void onCreate(Bundle b){super.onCreate(b);webView=new WebView(this);setContentView(webView);WebSettings s=webView.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setDatabaseEnabled(true);s.setSupportZoom(true);s.setBuiltInZoomControls(false);s.setDisplayZoomControls(false);s.setAllowFileAccess(true);s.setAllowContentAccess(true);webView.setWebChromeClient(new WebChromeClient());webView.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){return false;}});webView.loadUrl("file:///android_asset/index.html");}@Override public void onBackPressed(){if(webView!=null&&webView.canGoBack())webView.goBack();else super.onBackPressed();}}
